import urllib.request, re, time
h={'User-Agent':'x'}
found=[]
for page in range(1,12):
    u=f'https://github.com/istio/ztunnel/commits/master/common/scripts/setup_env.sh.atom?page={page}'
    try:
        r=urllib.request.urlopen(urllib.request.Request(u, headers=h), timeout=10)
        data=r.read().decode()
    except Exception as e:
        print('page',page,'ERR',e); break
    entries=re.findall(r'<entry>.*?<id>tag:github.com,2008:Grit::Commit/([0-9a-f]{40})</id>.*?<title>(.*?)</title>.*?<updated>(.*?)</updated>', data, re.S)
    if not entries:
        break
    for sha,t,upd in entries:
        t=t.replace('&#39;',chr(39)).strip().replace('\n',' ')[:100]
        found.append((upd[:10],sha,t))
    print('page',page,'count',len(entries)); time.sleep(0.3)
print('TOTAL',len(found))
for upd,sha,t in found:
    print(upd,sha,t)
" 2>&1 | tail -70

