impl ConnectionManager {
    pub fn new() -> Self {
        ConnectionManager(Arc::new(RwLock::new(HashMap::new())))
    }

    // register should be called when a new connection is established.
    pub fn register(&self, c: &Connection) {
        let mut conns = self.0.write().unwrap();
        conns.entry(c.clone()).or_insert_with(|| {
            let (tx, rx) = drain::channel();
            ConnectionDrain { tx, rx, count: 0 }
        });
    }

    // track should be called when a new task is spawned to handle a connection.
    pub fn track(&self, c: &Connection) -> Option<Watch> {
        let mut conns = self.0.write().unwrap();
        let conn = conns.get_mut(c)?;
        conn.count += 1;
        Some(conn.rx.clone())
    }

    // release should be called when a task handling a connection completes.
    pub fn release(&self, c: &Connection) {
        let mut conns = self.0.write().unwrap();
        let Some(conn) = conns.get_mut(c) else {
            return;
        };
        conn.count = conn.count.saturating_sub(1);
        if conn.count == 0 {
            // If we are the last one out, remove the connection and drain it.
            conns.remove(c);
            conn.tx.drain();
        }
    }

    // drain will signal all watchers on a connection to close, waiting for all tasks to complete.
    pub async fn drain(&self, c: &Connection) {
        let tx = {
            let conns = self.0.read().unwrap();
            match conns.get(c) {
                Some(conn) => conn.tx.clone(),
                None => return,
            }
        };
        // Signal all the watchers, then wait for them to be dropped.
        let remaining = tx.drain();
        let _ = remaining.await;
    }

    pub async fn drain_all(&self) {
        let conns: Vec<Connection> = self.0.read().unwrap().keys().cloned().collect();
        for c in conns {
            self.drain(&c).await;
        }
    }
}
