#[derive(Clone, Default)]
pub struct ConnectionManager {
    conns: Arc<RwLock<HashMap<Connection, ConnectionDrain>>>,
}

struct ConnectionDrain {
    tx: drain::Signal,
    rx: drain::Watch,
    count: usize,
}

impl ConnectionManager {
    fn register(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        conns.entry(c.clone()).or_insert_with(|| {
            let (tx, rx) = drain::channel();
            ConnectionDrain { tx, rx, count: 0 }
        });
    }

    fn track(&self, c: &Connection) -> Option<Watch> {
        let mut conns = self.conns.write().unwrap();
        let conn = conns.get_mut(c)?;
        conn.count += 1;
        Some(conn.rx.clone())
    }

    fn release(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        let Some(conn) = conns.get_mut(c) else { return };
        conn.count = conn.count.saturating_sub(1);
        if conn.count == 0 {
            conns.remove(c);
            conn.tx.drain(); // fire signal to release any held watches
        }
    }

    async fn drain(&self, c: &Connection) {
        let tx = {
            let mut conns = self.conns.write().unwrap();
            conns.remove(c).map(|cd| cd.tx)
        };
        let Some(tx) = tx else { return };
        tx.drain().await;
    }

    async fn drain_all(&self) {
        let conns: Vec<_> = {
            let conns = self.conns.write().unwrap();
            conns.keys().cloned().collect()
        };
        for c in conns {
            self.drain(&c).await;
        }
    }

    fn clear(&self) {
        self.conns.write().unwrap().clear();
    }

    // helper for policy_watcher
    fn conns(&self) -> Vec<Connection> {
        self.conns.read().unwrap().keys().cloned().collect()
    }
}
```

