// ConnectionManager stores all active connections, providing the ability to close individual
// connections or all connections on a policy change.
#[derive(Clone, Default)]
pub struct ConnectionManager {
    // We use a RW lock for read-heavy access in practice.
    conns: Arc<RwLock<HashMap<Connection, ConnectionDrain>>>,
}

impl ConnectionManager {
    pub fn new() -> Self {
        Self::default()
    }

    // register should be called when a connection is first created. This stores the
    // connection in the map so it can be later tracked and drained.
    pub fn register(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        conns.entry(c.clone()).or_insert_with(|| {
            let (tx, rx) = drain::channel();
            ConnectionDrain {
                tx,
                rx,
                count: 0,
            }
        });
    }

    // track should be called when a connection is actually being used (IE a task is handling it).
    // This will return a Watch which can be used to know when the connection is being drained.
    pub fn track(&self, c: &Connection) -> Option<Watch> {
        let mut conns = self.conns.write().unwrap();
        let drain = conns.get_mut(c)?;
        drain.count += 1;
        Some(drain.rx.clone())
    }

    // release should be called when a connection is no longer being used.
    pub fn release(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        let Some(drain) = conns.get_mut(c) else {
            return;
        };
        drain.count -= 1;
        if drain.count == 0 {
            // If we are the last one tracking this connection, we can remove it.
            conns.remove(c);
            drain.tx.drain();
        }
    }

    // drain should be called to signal all connection tasks to close.
    pub async fn drain(&self, c: &Connection) {
        let tx = self.conns.read().unwrap().get(c).map(|d| d.tx.clone());
        if let Some(tx) = tx {
            let _ = tx.drain().await;
        }
    }
}

