use std::collections::HashMap;
use std::sync::Arc;
use std::sync::RwLock;

use drain::Watch;
use tokio::sync::watch;
use tracing::{debug, error, info};

use crate::rbac::Connection;
use crate::state::DemandProxyState;

// ConnectionManager tracks all active connections and provides a mechanism to close
// individual connections when a policy update makes them invalid.
#[derive(Clone, Default)]
pub struct ConnectionManager {
    // We use a RWLock and Arc to allow access from multiple threads.
    conns: Arc<RwLock<HashMap<Connection, ConnectionDrain>>>,
}

// Tracks a single connection, allowing us to signal tasks handling the connection
// to close, and to track how many tasks are still active.
struct ConnectionDrain {
    // Signals to tasks handling the connection that the connection should be closed.
    tx: drain::Signal,
    // Watches for the drain signal; a clone is provided to each tracked task.
    rx: drain::Watch,
    // The number of tasks currently handling this connection.
    count: usize,
}

impl ConnectionManager {
    pub fn new() -> Self {
        Self::default()
    }

    // register should be called when a connection is established, before it is tracked.
    // This ensures the connection is known to the ConnectionManager, and can be drained
    // by the policy watcher.
    pub async fn register(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        conns.entry(c.clone()).or_insert_with(|| {
            let (tx, rx) = drain::channel();
            ConnectionDrain { tx, rx, count: 0 }
        });
    }

    // track should be called when a connection is actually used (IE a task starts
    // transferring data). It will return a Watch which the task should hold for the
    // lifetime of the connection. When the watch is signaled, the connection should be
    // closed.
    // Returns None if the connection was not registered.
    pub async fn track(&self, c: &Connection) -> Option<Watch> {
        let mut conns = self.conns.write().unwrap();
        let cd = conns.get_mut(c)?;
        cd.count += 1;
        Some(cd.rx.clone())
    }

    // release should be called when a task handling a connection is done. When the last
    // task releases the connection, the connection is removed and drained.
    pub async fn release(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        let Some(cd) = conns.get_mut(c) else {
            return;
        };
        cd.count = cd.count.saturating_sub(1);
        if cd.count == 0 {
            conns.remove(c);
            // Signal any remaining watchers, in case any task is still holding a watch.
            cd.tx.drain();
        }
    }

    // drain signals all tasks handling the connection to close, and waits for them
    // to release the connection.
    pub async fn drain(&self, c: &Connection) {
        let tx = {
            let mut conns = self.conns.write().unwrap();
            conns.remove(c).map(|cd| cd.tx)
        };
        let Some(tx) = tx else {
            return;
        };
        let _ = tx.drain().await;
    }

    // drain_all signals all tracked connections to close, waiting for each to release.
    pub async fn drain_all(&self) {
        let conns: Vec<Connection> = {
            let conns = self.conns.read().unwrap();
            conns.keys().cloned().collect()
        };
        for c in conns {
            self.drain(&c).await;
        }
    }

    // clear removes all tracked connections without draining them.
    pub fn clear(&self) {
        self.conns.write().unwrap().clear();
    }

    fn conns(&self) -> Vec<Connection> {
        let conns = self.conns.read().unwrap();
        conns.keys().cloned().collect()
    }
}

