use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use drain::Watch;
use tokio::sync::watch;
use tracing::{debug, error, info};

use crate::rbac::Connection;
use crate::state::DemandProxyState;

/// ConnectionManager tracks all active connections, providing a mechanism to signal
/// tasks handling a connection to close when it is no longer allowed by policy.
#[derive(Clone, Default)]
pub struct ConnectionManager {
    // We use a read-write lock and Arc, as the map is shared across all connection tasks
    // and the policy watcher task.
    conns: Arc<RwLock<HashMap<Connection, ConnectionDrain>>>,
}

/// State for a single connection, allowing us to signal tasks handling it to close,
/// and to track the number of tasks still active.
struct ConnectionDrain {
    // Signals tasks that the connection should be closed.
    tx: drain::Signal,
    // Watches the drain signal; a clone is provided to each tracked task.
    rx: drain::Watch,
    // The number of active tasks handling this connection.
    count: usize,
}

impl ConnectionManager {
    pub fn new() -> Self {
        Self::default()
    }

    /// register should be called when a connection is established, so that it is known
    /// to the ConnectionManager and can be closed if the policy changes. This must be
    /// called before track.
    pub async fn register(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        conns.entry(c.clone()).or_insert_with(|| {
            let (tx, rx) = drain::channel();
            ConnectionDrain { tx, rx, count: 0 }
        });
    }

    /// track should be called when a task starts handling a connection. It returns a
    /// Watch which the task should hold for the lifetime of the connection. When the
    /// watch is signaled, the task should close the connection.
    ///
    /// Returns None if the connection was not registered.
    pub async fn track(&self, c: &Connection) -> Option<Watch> {
        let mut conns = self.conns.write().unwrap();
        let drain = conns.get_mut(c)?;
        drain.count += 1;
        Some(drain.rx.clone())
    }

    /// release should be called when a task handling a connection is done. When the last
    /// task releases the connection, it is removed and any remaining watchers are signaled.
    pub async fn release(&self, c: &Connection) {
        let mut conns = self.conns.write().unwrap();
        let Some(drain) = conns.get_mut(c) else {
            return;
        };
        drain.count = drain.count.saturating_sub(1);
        if drain.count == 0 {
            conns.remove(c);
            // Signal any remaining watchers, in case a task is still holding a watch.
            drain.tx.drain();
        }
    }

    /// drain signals all tasks handling the connection to close, and waits for them
    /// to release the connection.
    pub async fn drain(&self, c: &Connection) {
        let tx = {
            let mut conns = self.conns.write().unwrap();
            conns.remove(c).map(|drain| drain.tx)
        };
        let Some(tx) = tx else {
            return;
        };
        let _ = tx.drain().await;
    }

    /// drain_all signals all tracked connections to close, waiting for each to release.
    pub async fn drain_all(&self) {
        let conns: Vec<Connection> = {
            let conns = self.conns.read().unwrap();
            conns.keys().cloned().collect()
        };
        for c in conns {
            self.drain(&c).await;
        }
    }

    /// clear removes all tracked connections without draining them.
    pub fn clear(&self) {
        self.conns.write().unwrap().clear();
    }

    fn conns(&self) -> Vec<Connection> {
        let conns = self.conns.read().unwrap();
        conns.keys().cloned().collect()
    }
}

/// policy_watcher reacts to authorization policy updates, closing any active connections
/// which are no longer allowed by the updated policy.
pub(crate) async fn policy_watcher(
    state: DemandProxyState,
    mut updates: watch::Receiver<()>,
    cm: ConnectionManager,
    scope: &str,
    drain: Watch,
) {
    loop {
        tokio::select! {
            // Begin drain; exit.
            _ = drain.signaled() => {
                debug!(scope, "policy watcher shutting down");
                return;
            }
            // Wait for a policy update notification.
            changed = updates.changed() => {
                if changed.is_err() {
                    // The policy store was dropped; there is nothing left to watch.
                    debug!(scope, "policy watcher shutting down");
                    return;
                }
                for conn in cm.conns() {
                    if !state.assert_rbac(&conn).await {
                        info!(scope, %conn, "closing connection due to policy change");
                        cm.drain(&conn).await;
                    }
                }
            }
        }
    }
}

